	if in.LatestCollectionAt != nil && *in.LatestCollectionAt != "" {
		if t, err := time.Parse(time.RFC3339, *in.LatestCollectionAt); err == nil {
			latestAt = t
		}
	}

	// 1. Dry run serviceability check
	checkRes, err := CheckServiceability(ctx, CheckServiceabilityInput{
		Origin:               in.Origin,
		OriginType:           in.OriginType,
		OriginNodeId:         in.OriginNodeId,
