`, sampleID, requestID, requesterID, in.SampleTypeId, in.Origin.Latitude, in.Origin.Longitude)
		if err != nil {
			return nil, err
		}

		_ = RecordAudit(ctx, actorID, actorRole, actorRole, "sample.create_request", "request", requestID, false, map[string]any{
