		_ = FindAndOfferWorker(ctx, nodeAssignID)
		seq++

		// Handoff Stop at fromNode
		stopID := uuid.New().String()
		loc, _ := GetLocationByID(ctx, fromNode)
		lat, lng := 0.0, 0.0
		if loc != nil {
			lat, lng = loc.Coordinate.Latitude, loc.Coordinate.Longitude
		}
		_, _ = db.Pool.Exec(ctx, `
