		seq++
		currentTime = currentTime.Add(10 * time.Minute)

		// Transport assignment between fromNode and toNode
		transAssignID := uuid.New().String()
		assignmentIDs = append(assignmentIDs, transAssignID)
		_, _ = db.Pool.Exec(ctx, `
INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, from_location_id, to_location_id, expected_sample_type_id)
VALUES ($1, $2, $3, 'transport', $4, 'offered', $5, $6, $7);
