	_, _ = db.Pool.Exec(ctx, `
INSERT INTO journey_stops (id, journey_id, location_id, stop_type, sequence, estimated_at, dwell_minutes, latitude, longitude)
VALUES ($1, $2, $3, 'delivery', $4, $5, 20, $6, $7);
`, finalStopID, journeyID, targetLabID, seq, estDeliveryTime, lat, lng)

	// Lab Assignment
	labAssignID := uuid.New().String()
	assignmentIDs = append(assignmentIDs, labAssignID)
	_, _ = db.Pool.Exec(ctx, `
INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, status, laboratory_id, expected_sample_type_id)
