`, labAssignID, journeyID, sampleID, seq, targetLabID, in.SampleTypeId)
	_ = FindAndOfferWorker(ctx, labAssignID)

	// Reserve lab capacity
	_, _ = db.Pool.Exec(ctx, `
UPDATE locations
SET reserved_units = CASE WHEN $1 = false THEN reserved_units + 1 ELSE reserved_units END,
    cooled_reserved_units = CASE WHEN $1 = true THEN cooled_reserved_units + 1 ELSE cooled_reserved_units END
