`, journeyID, sampleID, targetLabID, isCooled)

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "sample.create_request", "request", requestID, true, map[string]any{
		"sampleId":           sampleID,
		"journeyId":          journeyID,
		"targetLaboratoryId": targetLabID,
