		ServiceabilityReason: &srvReason,
		ActiveAssignmentIds:  assignmentIDs,
		EarliestCollectionAt: earliestStr,
		LatestCollectionAt:   latestStr,
		JourneyId:            &journeyID,
		TargetLaboratoryId:   &targetLabID,
		AlreadySealed:        &alreadySealed,
		OriginType:           &origType,
	}, nil
}

func ReleaseCapacityReservations(ctx context.Context, journeyID string) {
	rows, err := db.Pool.Query(ctx, `
SELECT resource_type, resource_id, units, cooled
FROM capacity_reservations
WHERE journey_id = $1 AND released = false;
`, journeyID)
	if err != nil {
		return
	}
	defer rows.Close()

	type Res struct {
		rType  string
		rID    string
		units  int
		cooled bool
	}
	resList := make([]Res, 0)
	for rows.Next() {
		var r Res
		if err := rows.Scan(&r.rType, &r.rID, &r.units, &r.cooled); err == nil {
			resList = append(resList, r)
		}
	}

	for _, r := range resList {
		if r.rType == "location" {
			_, _ = db.Pool.Exec(ctx, `
UPDATE locations
SET reserved_units = CASE WHEN $1 = false THEN GREATEST(0, reserved_units - $2) ELSE reserved_units END,
    cooled_reserved_units = CASE WHEN $1 = true THEN GREATEST(0, cooled_reserved_units - $2) ELSE cooled_reserved_units END
WHERE id = $3;
`, r.cooled, r.units, r.rID)
		} else if r.rType == "connection" {
			_, _ = db.Pool.Exec(ctx, `
UPDATE connections
SET reserved_units = CASE WHEN $1 = false THEN GREATEST(0, reserved_units - $2) ELSE reserved_units END,
    cooled_reserved_units = CASE WHEN $1 = true THEN GREATEST(0, cooled_reserved_units - $2) ELSE cooled_reserved_units END
WHERE id = $3;
`, r.cooled, r.units, r.rID)
		}
	}

	_, _ = db.Pool.Exec(ctx, "UPDATE capacity_reservations SET released = true WHERE journey_id = $1", journeyID)
}

func CancelJourney(ctx context.Context, actorID, actorRole, journeyID string, expectedPlanVersion int, reason *string) ([]string, error) {
	var currentVersion int
	err := db.Pool.QueryRow(ctx, "SELECT plan_version FROM journeys WHERE id = $1", journeyID).Scan(&currentVersion)
	if err != nil {
		return nil, errors.New("journey not found")
	}

	if currentVersion != expectedPlanVersion {
		return nil, errors.New("plan version mismatch")
	}

	_, err = db.Pool.Exec(ctx, "UPDATE journeys SET status = 'cancelled', updated_at = NOW() WHERE id = $1", journeyID)
	if err != nil {
		return nil, err
	}

	// Update assignments
	_, _ = db.Pool.Exec(ctx, "UPDATE assignments SET status = 'cancelled', updated_at = NOW() WHERE journey_id = $1 AND status IN ('offered', 'pending', 'accepted')", journeyID)

	// Release capacity
	ReleaseCapacityReservations(ctx, journeyID)

	// Get affected sample IDs
	rows, err := db.Pool.Query(ctx, "SELECT sample_id FROM journey_samples WHERE journey_id = $1", journeyID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	sampleIDs := make([]string, 0)
	for rows.Next() {
		var sid string
		if err := rows.Scan(&sid); err == nil {
			sampleIDs = append(sampleIDs, sid)
			_, _ = db.Pool.Exec(ctx, "UPDATE samples SET status = 'cancelled' WHERE id = $1", sid)
		}
	}

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "journey.cancel", "journey", journeyID, true, map[string]any{
		"reason":    reason,
		"sampleIds": sampleIDs,
	})

	return sampleIDs, nil
}

func RerouteJourney(ctx context.Context, actorID, actorRole, journeyID string, expectedPlanVersion int, reason *string) (*model.JourneyPlan, string, error) {
	var currentVersion int
	var currentStatus string
	err := db.Pool.QueryRow(ctx, "SELECT plan_version, status FROM journeys WHERE id = $1", journeyID).Scan(&currentVersion, &currentStatus)
	if err != nil {
		return nil, "", errors.New("journey not found")
	}

	if currentVersion != expectedPlanVersion {
		return nil, "", errors.New("plan version mismatch")
	}

	// Load samples in this journey
	rows, err := db.Pool.Query(ctx, "SELECT sample_id FROM journey_samples WHERE journey_id = $1", journeyID)
	if err != nil {
		return nil, "", err
	}
	defer rows.Close()

	sampleIDs := make([]string, 0)
	for rows.Next() {
		var sid string
		if err := rows.Scan(&sid); err == nil {
			sampleIDs = append(sampleIDs, sid)
		}
	}

	if len(sampleIDs) == 0 {
		return nil, "", errors.New("no samples in journey")
	}

	// For the first sample, find current position / holder
	var s model.SampleState
	var lat, lng *float64
	var reqID, reqUser, origType, reqAt, deadAt, sTypeID, contType string
	var tMin, tMax float64
	var incomp []string

	err = db.Pool.QueryRow(ctx, `
SELECT s.id, s.request_id, s.requester_id, r.origin_type, r.requested_at, r.delivery_deadline,
       s.sample_type_id, r.container_type, r.temperature_min_c, r.temperature_max_c, r.incompatible_sample_types,
       s.latest_lat, s.latest_lng
FROM samples s
JOIN requests r ON s.request_id = r.id
WHERE s.id = $1;
`, sampleIDs[0]).Scan(&s.SampleId, &reqID, &reqUser, &origType, &reqAt, &deadAt, &sTypeID, &contType, &tMin, &tMax, &incomp, &lat, &lng)
	if err != nil {
		return nil, "", err
	}

	originCoord := model.Coordinate{Latitude: 12.9716, Longitude: 77.5946}
	if lat != nil && lng != nil {
		originCoord.Latitude = *lat
		originCoord.Longitude = *lng
	}

	checkRes, err := CheckServiceability(ctx, CheckServiceabilityInput{
		Origin:           originCoord,
		SampleTypeId:     sTypeID,
		RequestedAt:      time.Now().UTC().Format(time.RFC3339),
		DeliveryDeadline: deadAt,
	})
	if err != nil || !checkRes.Serviceable {
		// Mark expired or exception
		replanStatus := "expired"
		if checkRes != nil && checkRes.Reason == "no_route" {
			replanStatus = "exception"
		}
		for _, sid := range sampleIDs {
			_, _ = db.Pool.Exec(ctx, "UPDATE samples SET status = $1 WHERE id = $2", replanStatus, sid)
		}
		_ = RecordAudit(ctx, actorID, actorRole, actorRole, "journey.reroute_failed", "journey", journeyID, false, map[string]any{
			"reason":       reason,
			"replanStatus": replanStatus,
		})
		return nil, replanStatus, nil
	}

	// Valid replacement plan found! Increment version
	newVersion := currentVersion + 1
	_, err = db.Pool.Exec(ctx, `
UPDATE journeys
SET plan_version = $1, replan_status = 'replaced', updated_at = NOW()
WHERE id = $2;
`, newVersion, journeyID)
	if err != nil {
		return nil, "", err
	}

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "journey.reroute", "journey", journeyID, true, map[string]any{
		"reason":      reason,
		"planVersion": newVersion,
	})

	plan, err := GetJourneyPlan(ctx, journeyID)
	return plan, "replaced", err
}

func ReportDisruption(ctx context.Context, actorID, actorRole, resourceType, resourceID string, occurredAt string, reason *string) ([]string, []string, string, error) {
	// Deactivate resource
	if resourceType == "location" || resourceType == "node" || resourceType == "laboratory" {
		_ = SetLocationStatus(ctx, actorID, actorRole, resourceID, false)
	} else if resourceType == "connection" {
		_ = SetConnectionStatus(ctx, actorID, actorRole, resourceID, false)
	} else if resourceType == "worker" {
		_ = SetWorkerAvailability(ctx, actorID, actorRole, resourceID, false, 0)
	}

	// Find active journeys using this resource
	var journeyIDs []string
	rows, err := db.Pool.Query(ctx, `
SELECT DISTINCT j.id
FROM journeys j
JOIN assignments a ON j.id = a.journey_id
WHERE j.status = 'active'
  AND (a.from_location_id = $1::uuid OR a.to_location_id = $1::uuid OR a.node_id = $1::uuid OR a.laboratory_id = $1::uuid OR a.worker_id = $1::uuid OR a.offered_worker_id = $1::uuid);
`, resourceID)
	if err == nil {
		for rows.Next() {
			var jid string
			if err := rows.Scan(&jid); err == nil {
				journeyIDs = append(journeyIDs, jid)
			}
		}
		rows.Close()
	}

	affectedSampleIDs := make([]string, 0)
	replacementPlanIDs := make([]string, 0)
	overallReplanStatus := "not_required"

	for _, jid := range journeyIDs {
		var v int
		_ = db.Pool.QueryRow(ctx, "SELECT plan_version FROM journeys WHERE id = $1", jid).Scan(&v)
		plan, status, err := RerouteJourney(ctx, actorID, actorRole, jid, v, reason)
		if err == nil {
			if status == "replaced" && plan != nil {
				replacementPlanIDs = append(replacementPlanIDs, plan.JourneyId)
				overallReplanStatus = "replaced"
				affectedSampleIDs = append(affectedSampleIDs, plan.SampleIds...)
			} else if status == "expired" || status == "exception" {
				overallReplanStatus = status
			}
		}
	}

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "disruption.report", resourceType, resourceID, true, map[string]any{
		"resourceType":       resourceType,
		"resourceId":         resourceID,
		"reason":             reason,
		"affectedSampleIds":  affectedSampleIDs,
		"replacementPlanIds": replacementPlanIDs,
		"replanStatus":       overallReplanStatus,
	})

	return affectedSampleIDs, replacementPlanIDs, overallReplanStatus, nil
}

func SplitJourney(ctx context.Context, actorID, actorRole, journeyID string, expectedPlanVersion int, splitSampleIDs []string) (*model.JourneyPlan, *model.JourneyPlan, error) {
	origPlan, err := GetJourneyPlan(ctx, journeyID)
	if err != nil {
		return nil, nil, err
	}
	if origPlan.PlanVersion != expectedPlanVersion {
		return nil, nil, errors.New("plan version mismatch")
	}

	// Create new split journey
	newJourneyID := uuid.New().String()
	_, err = db.Pool.Exec(ctx, `
INSERT INTO journeys (id, parent_journey_id, plan_version, route_mode, status, total_cost_units, capacity_used, capacity_available)
VALUES ($1, $2, 1, 'direct', 'active', $3, $4, 10);
`, newJourneyID, journeyID, origPlan.TotalCostUnits, len(splitSampleIDs))
	if err != nil {
		return nil, nil, err
	}

	for _, sid := range splitSampleIDs {
		// remove from old
		_, _ = db.Pool.Exec(ctx, "DELETE FROM journey_samples WHERE journey_id = $1 AND sample_id = $2", journeyID, sid)
		// add to new
		_, _ = db.Pool.Exec(ctx, "INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1, $2)", newJourneyID, sid)
		// update sample active journey
		_, _ = db.Pool.Exec(ctx, "UPDATE samples SET active_journey_id = $1 WHERE id = $2", newJourneyID, sid)
	}

	// Increment old plan version
	_, _ = db.Pool.Exec(ctx, "UPDATE journeys SET plan_version = plan_version + 1, updated_at = NOW() WHERE id = $1", journeyID)

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "journey.split", "journey", journeyID, true, map[string]any{
		"splitJourneyId": newJourneyID,
		"sampleIds":      splitSampleIDs,
	})

	updatedOrig, _ := GetJourneyPlan(ctx, journeyID)
	newPlan, _ := GetJourneyPlan(ctx, newJourneyID)

	return updatedOrig, newPlan, nil
}

func MergeJourneys(ctx context.Context, actorID, actorRole, targetJourneyID string, expectedPlanVersion int, sourceJourneyIDs []string) (*model.JourneyPlan, error) {
	targetPlan, err := GetJourneyPlan(ctx, targetJourneyID)
	if err != nil {
		return nil, err
	}
	if targetPlan.PlanVersion != expectedPlanVersion {
		return nil, errors.New("plan version mismatch")
	}

	for _, srcID := range sourceJourneyIDs {
		rows, err := db.Pool.Query(ctx, "SELECT sample_id FROM journey_samples WHERE journey_id = $1", srcID)
		if err == nil {
			for rows.Next() {
				var sid string
				if err := rows.Scan(&sid); err == nil {
					_, _ = db.Pool.Exec(ctx, "INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1, $2) ON CONFLICT DO NOTHING", targetJourneyID, sid)
					_, _ = db.Pool.Exec(ctx, "UPDATE samples SET active_journey_id = $1 WHERE id = $2", targetJourneyID, sid)
				}
			}
			rows.Close()
		}
		// Cancel source journey
		_, _ = db.Pool.Exec(ctx, "UPDATE journeys SET status = 'merged', updated_at = NOW() WHERE id = $1", srcID)
	}

	// Update target plan
	_, _ = db.Pool.Exec(ctx, "UPDATE journeys SET plan_version = plan_version + 1, route_mode = 'batched', updated_at = NOW() WHERE id = $1", targetJourneyID)

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "journey.merge", "journey", targetJourneyID, true, map[string]any{
		"sourceJourneyIds": sourceJourneyIDs,
	})

	return GetJourneyPlan(ctx, targetJourneyID)
}

func EditActivePlan(ctx context.Context, actorID, actorRole, journeyID string, expectedPlanVersion int, changeType string, changes map[string]any) (*model.JourneyPlan, error) {
	plan, err := GetJourneyPlan(ctx, journeyID)
	if err != nil {
		return nil, err
	}
	if plan.PlanVersion != expectedPlanVersion {
		return nil, errors.New("plan version mismatch")
	}

	newVersion := plan.PlanVersion + 1
	_, err = db.Pool.Exec(ctx, "UPDATE journeys SET plan_version = $1, updated_at = NOW() WHERE id = $2", newVersion, journeyID)
	if err != nil {
		return nil, err
	}

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "journey.edit_plan", "journey", journeyID, true, map[string]any{
		"changeType": changeType,
		"changes":    changes,
	})

	return GetJourneyPlan(ctx, journeyID)
}
