func CollectAndSealSample(ctx context.Context, actorID, actorRole, sampleID, assignmentID string, collectedAt string, containerType string, observedTemp float64) (string, string, string, string, bool, error) {
	var stID string
	err := db.Pool.QueryRow(ctx, "SELECT sample_type_id FROM samples WHERE id = $1", sampleID).Scan(&stID)
	if err != nil {
		return "", "", "", "", false, errors.New("sample not found")
	}

	st, err := GetSampleTypeByID(ctx, stID)
	if err != nil {
		return "", "", "", "", false, err
	}

	handlingCompliant := true
	if observedTemp < st.TemperatureMinC || observedTemp > st.TemperatureMaxC {
		handlingCompliant = false
	}
	if containerType != "" && st.ContainerType != "" && containerType != st.ContainerType {
		handlingCompliant = false
	}

	cTime, err := time.Parse(time.RFC3339, collectedAt)
	if err != nil {
		cTime = time.Now().UTC()
	}

	sampleStatus := "sealed"
	if !handlingCompliant {
		sampleStatus = "exception"
		_, _ = db.Pool.Exec(ctx, `
UPDATE samples
SET status = $1, sealed = true, sealed_at = $2, current_holder_id = $3,
    exception_details = jsonb_build_object('reason', 'handling_non_compliant', 'temperature', $4, 'container', $5)
WHERE id = $6;
`, sampleStatus, cTime, actorID, observedTemp, containerType, sampleID)
	} else {
		_, _ = db.Pool.Exec(ctx, `
UPDATE samples
SET status = $1, sealed = true, sealed_at = $2, current_holder_id = $3
WHERE id = $4;
`, sampleStatus, cTime, actorID, sampleID)
	}

	// Update assignment
	_, _ = db.Pool.Exec(ctx, "UPDATE assignments SET status = 'completed', updated_at = NOW() WHERE id = $1", assignmentID)

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "sample.collect_and_seal", "sample", sampleID, handlingCompliant, map[string]any{
		"assignmentId":      assignmentID,
		"containerType":     containerType,
		"observedTemp":      observedTemp,
		"handlingCompliant": handlingCompliant,
	})

	return sampleID, sampleStatus, actorID, cTime.UTC().Format(time.RFC3339), handlingCompliant, nil
}

func InitiateHandoff(ctx context.Context, actorID, actorRole, sampleID string, fromAssignmentID, toAssignmentID *string, receiverID, initiatedAt string) (string, string, string, string, string, error) {
	var currentHolderID *string
	err := db.Pool.QueryRow(ctx, "SELECT current_holder_id FROM samples WHERE id = $1", sampleID).Scan(&currentHolderID)
	if err != nil {
		return "", "", "", "", "", errors.New("sample not found")
	}

	senderID := actorID
	handoffID := uuid.New().String()

	_, err = db.Pool.Exec(ctx, `
INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, current_holder_id, status, sender_confirmed, receiver_confirmed, sender_confirmed_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, 'pending', true, false, NOW());
`, handoffID, sampleID, fromAssignmentID, toAssignmentID, senderID, receiverID, senderID)
	if err != nil {
		return "", "", "", "", "", err
	}

	_ = RecordAudit(ctx, actorID, actorRole, actorRole, "handoff.initiate", "handoff", handoffID, true, map[string]any{
		"sampleId":   sampleID,
		"senderId":   senderID,
