{"command":"create","file_text":"const API_BASE = '/api';

export class ApiError extends Error {
  code?: string;
  status: number;
  constructor(message: string, status: number, code?: string) {
    super(message);
    this.name = 'ApiError';
    this.status = status;
    this.code = code;
  }
}

let sessionToken: string | null = localStorage.getItem('sessionToken');

export const setAuthToken = (token: string | null) => {
  sessionToken = token;
  if (token) {
    localStorage.setItem('sessionToken', token);
  } else {
    localStorage.removeItem('sessionToken');
  }
};

export const getAuthToken = () => sessionToken;

async function request<T>(path: string, options: RequestInit = {}): Promise<T> {
  const headers = new Headers(options.headers || {});
  headers.set('Content-Type', 'application/json');

  if (sessionToken) {
    headers.set('Authorization', `Bearer ${sessionToken}`);
  }

  const response = await fetch(`${API_BASE}${path}`, {
    ...options,
    headers,
  });

  const responseText = await response.text();
  let json: any = null;
  if (responseText) {
    try {
      json = JSON.parse(responseText);
    } catch {
      json = null;
    }
  }

  if (!response.ok) {
    const errorMsg = json?.error || json?.message || response.statusText || 'Request failed';
    const errorCode = json?.code;
    throw new ApiError(errorMsg, response.status, errorCode);
  }

  return json?.data ?? json;
}

export const api = {
  // 1. Ready
  checkReady: () => fetch('/ready').then((r) => r.json()),

  // 2. Auth
  authenticateUser: (username: string, password: string) =>
    request<{ sessionToken: string; userId: string; roles: string[]; activeRole: string }>(
      '/authenticate-user',
      {
        method: 'POST',
        body: JSON.stringify({ username, password }),
      }
    ),

  selectActiveRole: (role: string) =>
    request<{ userId: string; activeRole: string }>('/select-active-role', {
      method: 'POST',
      body: JSON.stringify({ role }),
    }),

  getUser: (userId: string) => request<any>(`/read-user/${userId}`, { method: 'GET' }),

  createUser: (data: {
    username: string;
    password: string;
    fullName: string;
    roles: string[];
    assignedNodeId?: string;
    assignedLaboratoryId?: string;
    certifications?: string[];
  }) => request<any>('/create-user', { method: 'POST', body: JSON.stringify(data) }),

  updateUserAccess: (data: {
    userId: string;
    roles?: string[];
    assignedNodeId?: string;
    assignedLaboratoryId?: string;
    certifications?: string[];
    isActive?: boolean;
  }) => request<any>('/update-user-access', { method: 'POST', body: JSON.stringify(data) }),

  setWorkerAvailability: (isAvailable: boolean) =>
    request<any>('/set-worker-availability', {
      method: 'POST',
      body: JSON.stringify({ isAvailable }),
    }),

  // Serviceability & Network
  checkServiceability: (data: {
    originLatitude: number;
    originLongitude: number;
    sampleTypeId: string;
    collectionWindowEarliest: string;
    collectionWindowLatest: string;
    deliveryDeadline: string;
  }) => request<any>('/check-serviceability', { method: 'POST', body: JSON.stringify(data) }),

  readServiceabilitySnapshot: () =>
    request<any>('/read-serviceability-snapshot', { method: 'POST', body: JSON.stringify({}) }),

  createLocation: (data: any) =>
    request<any>('/create-location', { method: 'POST', body: JSON.stringify(data) }),

  updateLocation: (data: any) =>
    request<any>('/update-location', { method: 'POST', body: JSON.stringify(data) }),

  setLocationStatus: (locationId: string, isActive: boolean) =>
    request<any>('/set-location-status', {
      method: 'POST',
      body: JSON.stringify({ locationId, isActive }),
    }),

  setLocationFunctionStatus: (locationId: string, functionName: string, isActive: boolean) =>
    request<any>('/set-location-function-status', {
      method: 'POST',
      body: JSON.stringify({ locationId, functionName, isActive }),
    }),

  createConnection: (data: any) =>
    request<any>('/create-connection', { method: 'POST', body: JSON.stringify(data) }),

  setConnectionStatus: (connectionId: string, active: boolean) =>
    request<any>('/set-connection-status', {
      method: 'POST',
      body: JSON.stringify({ connectionId, active }),
    }),

  configureCapacity: (resourceId: string, capacityUnits: number, cooledCapacityUnits: number) =>
    request<any>('/configure-capacity', {
      method: 'POST',
      body: JSON.stringify({ resourceId, capacityUnits, cooledCapacityUnits }),
    }),

  configureLaboratoryAcceptance: (laboratoryId: string, sampleTypeId: string, accepts: boolean) =>
    request<any>('/configure-laboratory-acceptance', {
      method: 'POST',
      body: JSON.stringify({ laboratoryId, sampleTypeId, accepts }),
