{"path":"/workspace/frontend/src/context/AuthContext.tsx","security_risk":"LOW","command":"create","file_text":"import React, { createContext, useContext, useState, useEffect } from 'react';
import { User, UserRole } from '../types';
import { api, setAuthToken, getAuthToken } from '../api/client';

interface AuthContextType {
  user: User | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
  login: (username: string, password: string) => Promise<void>;
  switchRole: (newRole: UserRole) => Promise<void>;
  logout: () => void;
  refreshUser: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [isLoading, setIsLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  const fetchBootstrap = async () => {
    try {
      const data = await api.getUIBootstrap();
      if (data && data.user) {
        setUser({
          userId: data.user.userId,
          username: data.user.username,
          fullName: data.user.fullName,
          roles: data.user.roles || [],
          activeRole: data.user.activeRole || data.user.roles?.[0] || 'requester',
          roleSelectionRequired: data.user.roleSelectionRequired,
        });
      }
    } catch (err: any) {
      console.warn('Bootstrap fetch error, clearing session:', err);
      setAuthToken(null);
      setUser(null);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    const token = getAuthToken();
    if (token) {
      fetchBootstrap();
    } else {
      setIsLoading(false);
    }
  }, []);

  const login = async (username: string, password: string) => {
    setError(null);
    setIsLoading(true);
    try {
      const resp = await api.authenticateUser(username, password);
      setAuthToken(resp.sessionToken);
      const bootstrap = await api.getUIBootstrap();
      if (bootstrap && bootstrap.user) {
        setUser({
          userId: bootstrap.user.userId,
          username: bootstrap.user.username,
          fullName: bootstrap.user.fullName,
          roles: bootstrap.user.roles || [],
          activeRole: (resp.activeRole || bootstrap.user.activeRole || bootstrap.user.roles?.[0] || 'requester') as UserRole,
        });
      } else {
        setUser({
          userId: resp.userId,
          username,
          fullName: username,
          roles: (resp.roles || []) as UserRole[],
          activeRole: (resp.activeRole || resp.roles?.[0] || 'requester') as UserRole,
        });
      }
    } catch (err: any) {
      const msg = err.message || 'Authentication failed';
      setError(msg);
      throw err;
    } finally {
      setIsLoading(false);
    }
  };

  const switchRole = async (newRole: UserRole) => {
    if (!user) return;
    try {
      const res = await api.selectActiveRole(newRole);
      setUser((prev) => (prev ? { ...prev, activeRole: (res.activeRole || newRole) as UserRole } : null));
    } catch (err: any) {
      console.error('Failed to switch role:', err);
      throw err;
    }
  };

  const logout = () => {
    setAuthToken(null);
    setUser(null);
    setError(null);
  };

  const refreshUser = async () => {
    if (getAuthToken()) {
      await fetchBootstrap();
    }
  };

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated: !!user,
        isLoading,
        error,
        login,
        switchRole,
        logout,
        refreshUser,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
