{"file_text":"import React from 'react';
import { useAuth } from '../context/AuthContext';
import { UserRole } from '../types';
import { LogOut, User as UserIcon, Shield, RefreshCw } from 'lucide-react';

interface NavbarProps {
  currentTab: string;
  onTabChange: (tab: string) => void;
}

const ROLE_LABELS: Record<UserRole, string> = {
  requester: 'Requester',
  collection_professional: 'Certified Collection Pro',
  delivery_partner: 'Relay Courier',
  node_handler: 'Node Handler',
  laboratory_team: 'Lab Intake Operator',
  dispatcher: 'Dispatcher',
  administrator: 'Administrator',
};

export const Navbar: React.FC<NavbarProps> = ({ currentTab, onTabChange }) => {
  const { user, switchRole, logout } = useAuth();

  if (!user) return null;

  const handleRoleChange = async (e: React.ChangeEvent<HTMLSelectElement>) => {
    const newRole = e.target.value as UserRole;
    try {
      await switchRole(newRole);
      // Reset tab to default for that role
      if (newRole === 'requester') onTabChange('samples');
      else if (newRole === 'dispatcher' || newRole === 'administrator') onTabChange('operations');
      else if (newRole === 'laboratory_team') onTabChange('lab_work');
      else if (newRole === 'node_handler') onTabChange('node_work');
      else onTabChange('assignments');
    } catch (err) {
      console.error(err);
    }
  };

  const getNavTabs = () => {
    const role = user.activeRole;
    if (role === 'requester') {
      return [
        { id: 'samples', label: 'My Samples & Requests' },
        { id: 'serviceability', label: 'Serviceability Check' },
        { id: 'create_request', label: 'New Collection Request' },
      ];
    }
    if (role === 'collection_professional') {
      return [
        { id: 'assignments', label: 'Collection Work' },
        { id: 'ingest', label: 'Register Pre-sealed' },
        { id: 'map', label: 'Live Map' },
      ];
    }
    if (role === 'delivery_partner') {
      return [
        { id: 'assignments', label: 'Delivery Legs' },
        { id: 'ingest', label: 'Register Pre-sealed' },
        { id: 'map', label: 'Live Map' },
      ];
    }
    if (role === 'node_handler') {
      return [
        { id: 'assignments', label: 'Node Work' },
        { id: 'capacity', label: 'Node Capacity' },
        { id: 'ingest', label: 'Register Pre-sealed' },
        { id: 'map', label: 'Live Map' },
      ];
    }
    if (role === 'laboratory_team') {
      return [
        { id: 'assignments', label: 'Expected & Intake' },
        { id: 'capacity', label: 'Lab Capacity' },
        { id: 'map', label: 'Live Map' },
      ];
    }
    // dispatcher & administrator
    const tabs = [
      { id: 'operations', label: 'Operations Monitor' },
      { id: 'map', label: 'Live Map' },
      { id: 'audit', label: 'Audit Trail' },
    ];
    if (role === 'administrator') {
      tabs.push({ id: 'admin', label: 'Administration' });
    }
    return tabs;
  };

  const tabs = getNavTabs();

  return (
    <header className="bg-slate-900 text-white shadow-md sticky top-0 z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">
          {/* Logo & Title */}
          <div className="flex items-center space-x-3">
            <div className="w-9 h-9 rounded-lg bg-teal-500 flex items-center justify-center font-bold text-slate-950 text-xl tracking-wider">
              L
            </div>
            <div>
              <span className="font-bold text-lg tracking-tight">Lab Transport Network</span>
              <span className="hidden sm:inline-block ml-2 text-xs px-2 py-0.5 rounded bg-slate-800 text-teal-400 border border-teal-500/30">
                v1.0
              </span>
            </div>
          </div>

          {/* User Controls & Role Switcher */}
          <div className="flex items-center space-x-4">
            {/* Role Switcher */}
            <div className="flex items-center space-x-2 bg-slate-800/80 px-3 py-1.5 rounded-lg border border-slate-700">
              <Shield className="w-4 h-4 text-teal-400" />
              <label htmlFor="role-select" className="text-xs text-slate-300 font-medium mr-1">
                Active Role:
              </label>
              <select
                id="role-select"
                aria-label="Active Role"
                data-testid="role-switch-select"
                value={user.activeRole}
                onChange={handleRoleChange}
                className="bg-slate-900 text-teal-300 font-medium text-sm rounded border border-slate-600 px-2 py-1 focus:outline-none focus:ring-1 focus:ring-teal-400"
              >
                {user.roles.map((r) => (
                  <option key={r} value={r}>
                    {ROLE_LABELS[r] || r}
                  </option>
                ))}
              </select>
            </div>

            {/* User Profile */}
            <div className="hidden md:flex items-center space-x-2 text-slate-300 text-sm">
              <UserIcon className="w-4 h-4 text-slate-400" />
              <span className="font-medium">{user.fullName || user.username}</span>
            </div>

            {/* Sign Out Button */}
            <button
              onClick={logout}
              aria-label="Sign Out"
              data-testid="sign-out-button"
              className="flex items-center space-x-1 px-3 py-1.5 rounded-lg bg-slate-800 hover:bg-red-900/60 text-slate-300 hover:text-red-200 text-sm font-medium transition duration-150 border border-slate-700 hover:border-red-700"
            >
              <LogOut className="w-4 h-4" />
              <span>Sign Out</span>
            </button>
          </div>
        </div>

        {/* Tab Navigation */}
        <nav className="flex space-x-1 overflow-x-auto pb-2 pt-1 border-t border-slate-800">
          {tabs.map((tab) => {
            const active = currentTab === tab.id;
            return (
              <button
                key={tab.id}
                onClick={() => onTabChange(tab.id)}
                aria-label={tab.label}
                data-testid={`nav-tab-${tab.id}`}
                className={`px-3 py-1.5 text-sm font-medium rounded-md whitespace-nowrap transition-colors ${
                  active
                    ? 'bg-teal-500 text-slate-950 font-semibold shadow-sm'
                    : 'text-slate-300 hover:text-white hover:bg-slate-800'
                }`}
              >
                {tab.label}
              </button>
            );
          })}
        </nav>
      </div>
    </header>
  );
};
