import { StatusTimelineEvent } from '../types';
import { CheckCircle2, AlertTriangle, ArrowRight, Thermometer, Clock, MapPin, User } from 'lucide-react';

interface StatusTimelineProps {
  events: StatusTimelineEvent[];
}

export const StatusTimeline: React.FC<StatusTimelineProps> = ({ events }) => {
  if (!events || events.length === 0) {
    return (
      <div className="py-6 text-center text-slate-500 text-sm italic">
        No status history recorded yet.
      </div>
    );
  }

  // Sort chronologically ascending
  const sortedEvents = [...events].sort(
    (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime()
  );

  return (
    <div className="flow-root" data-testid="status-timeline">
      <ul className="-mb-8">
        {sortedEvents.map((event, idx) => {
          const isLast = idx === sortedEvents.length - 1;
          const isException =
            event.status?.toLowerCase().includes('exception') ||
            event.details?.toLowerCase().includes('exception') ||
            event.details?.toLowerCase().includes('failed');

          return (
            <li key={event.id || idx}>
              <div className="relative pb-8">
                {!isLast && (
                  <span
                    className="absolute top-4 left-4 -ml-px h-full w-0.5 bg-slate-200"
                    aria-hidden="true"
                  />
                )}
                <div className="relative flex space-x-3 items-start">
                  <div>
                    <span
                      className={`h-8 w-8 rounded-full flex items-center justify-center ring-4 ring-white ${
                        isException
                          ? 'bg-red-500 text-white'
                          : isLast
                          ? 'bg-teal-600 text-white'
                          : 'bg-slate-200 text-slate-600'
                      }`}
                    >
                      {isException ? (
                        <AlertTriangle className="w-4 h-4" />
                      ) : (
                        <CheckCircle2 className="w-4 h-4" />
                      )}
                    </span>
                  </div>
                  <div className="flex-1 min-w-0 bg-white p-3.5 rounded-lg border border-slate-200 shadow-sm">
                    <div className="flex items-center justify-between">
                      <h4 className="text-sm font-semibold text-slate-900 capitalize">
                        {event.status.replace(/_/g, ' ')}
                      </h4>
                      <time className="text-xs text-slate-500 flex items-center">
                        <Clock className="w-3.5 h-3.5 mr-1 text-slate-400" />
                        {new Date(event.timestamp).toLocaleString()}
                      </time>
                    </div>

                    {event.details && (
                      <p className="mt-1 text-sm text-slate-700">{event.details}</p>
                    )}

                    <div className="mt-2 flex flex-wrap gap-2 text-xs text-slate-600">
                      {event.actor_name && (
                        <span className="inline-flex items-center bg-slate-100 px-2 py-0.5 rounded text-slate-700 border border-slate-200">
                          <User className="w-3 h-3 mr-1 text-slate-500" />
                          {event.actor_name} ({event.actor_role || 'worker'})
                        </span>
                      )}

                      {event.location_name && (
                        <span className="inline-flex items-center bg-slate-100 px-2 py-0.5 rounded text-slate-700 border border-slate-200">
                          <MapPin className="w-3 h-3 mr-1 text-slate-500" />
                          {event.location_name}
                        </span>
                      )}

                      {typeof event.temperature_celsius === 'number' && (
                        <span className="inline-flex items-center bg-sky-50 text-sky-800 px-2 py-0.5 rounded border border-sky-200 font-medium">
                          <Thermometer className="w-3 h-3 mr-1 text-sky-600" />
                          {event.temperature_celsius}°C
                        </span>
                      )}

                      {event.container_type && (
                        <span className="inline-flex items-center bg-purple-50 text-purple-800 px-2 py-0.5 rounded border border-purple-200">
                          Container: {event.container_type}
                        </span>
                      )}
                    </div>
                  </div>
                </div>
              </div>
            </li>
          );
        })}
      </ul>
    </div>
  );
};
