    }
  };

  useEffect(() => {
    fetchWork();
  }, [user?.activeRole]);

  // Filter current vs past work
  const currentWork = workList.filter(
    (w) => w.status === 'offered' || w.status === 'accepted' || w.status === 'in_progress' || w.status === 'scheduled'
  );
  const pastWork = workList.filter(
    (w) => w.status === 'completed' || w.status === 'declined' || w.status === 'cancelled'
  );

  // Accept Assignment
  const handleAcceptAssignment = async (assignmentId: string) => {
    setActionLoading(assignmentId);
    setFeedback(null);
    try {
      await api.acceptAssignment(assignmentId);
      setFeedback({ type: 'success', message: 'Assignment accepted successfully!' });
      await fetchWork();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to accept assignment.' });
    } finally {
      setActionLoading(null);
    }
  };

  // Decline Assignment
  const handleDeclineAssignment = async (assignmentId: string) => {
    setActionLoading(assignmentId);
    setFeedback(null);
    try {
      await api.declineAssignment(assignmentId, 'Worker unavailable');
      setFeedback({ type: 'success', message: 'Assignment declined.' });
      await fetchWork();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to decline assignment.' });
    } finally {
      setActionLoading(null);
    }
  };

  // Record Worker Location
  const handleRecordLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading('location');
    setFeedback(null);
    try {
      await api.recordWorkerLocation({
        latitude: Number(locationForm.latitude),
        longitude: Number(locationForm.longitude),
        accuracyMeters: Number(locationForm.accuracyMeters),
        speedMps: Number(locationForm.speedMps),
      });
      setFeedback({ type: 'success', message: 'Current location recorded successfully!' });
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to record location.' });
    } finally {
      setActionLoading(null);
    }
  };

  // Collect and Seal Sample
  const handleCollectAndSeal = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!collectModal) return;
    setActionLoading('collect');
    setFeedback(null);
    try {
      await api.collectAndSealSample({
        assignmentId: collectModal.assignmentId,
        sampleId: collectModal.sampleId,
        containerType: collectForm.containerType,
        sealTag: collectForm.sealTag,
        observedTemperatureCelsius: Number(collectForm.temp),
      });
      setFeedback({ type: 'success', message: 'Sample collected and sealed successfully!' });
      setCollectModal(null);
      await fetchWork();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to seal sample.' });
    } finally {
      setActionLoading(null);
    }
  };

  // Record Handling Checkpoint
  const handleRecordCheckpoint = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!checkpointModal) return;
    setActionLoading('checkpoint');
    setFeedback(null);
    try {
      await api.recordHandlingCheckpoint({
        sampleId: checkpointModal.sampleId,
        containerType: checkpointForm.containerType,
        observedTemperatureCelsius: Number(checkpointForm.temp),
        locationId: checkpointForm.locationId || undefined,
        notes: checkpointForm.notes || undefined,
      });
      setFeedback({ type: 'success', message: 'Handling checkpoint recorded!' });
      setCheckpointModal(null);
      await fetchWork();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to record checkpoint.' });
    } finally {
      setActionLoading(null);
    }
  };

  // Confirm Laboratory Receipt
  const handleConfirmLabReceipt = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!labReceiptModal) return;
    setActionLoading('receipt');
    setFeedback(null);
    try {
      await api.confirmLaboratoryReceipt({
        sampleId: labReceiptModal.sampleId,
        laboratoryId: user?.assignedLaboratoryId || locations.find((l) => l.type === 'laboratory')?.id || '',
        containerType: labReceiptForm.containerType,
        observedTemperatureCelsius: Number(labReceiptForm.temp),
        conditionNotes: labReceiptForm.conditionNotes,
      });
      setFeedback({ type: 'success', message: 'Sample receipt confirmed at laboratory!' });
      setLabReceiptModal(null);
      await fetchWork();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to confirm receipt.' });
    } finally {
      setActionLoading(null);
    }
  };

  // Record Laboratory Exception
  const handleRecordLabException = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!labExceptionModal) return;
    setActionLoading('exception');
    setFeedback(null);
    try {
      await api.recordLaboratoryException({
        sampleId: labExceptionModal.sampleId,
        laboratoryId: user?.assignedLaboratoryId || locations.find((l) => l.type === 'laboratory')?.id || '',
        reason: labExceptionForm.reason,
        observedAt: new Date(labExceptionForm.observedAt).toISOString(),
      });
      setFeedback({ type: 'success', message: 'Laboratory exception recorded on sample.' });
      setLabExceptionModal(null);
      await fetchWork();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to record exception.' });
    } finally {
      setActionLoading(null);
    }
  };

  // Register Pre-sealed Sample
  const handleIngestPresealed = async (e: React.FormEvent) => {
    e.preventDefault();
    setActionLoading('ingest');
    setFeedback(null);
    try {
      const res = await api.ingestPresealedSample({
        originLocationId: presealedForm.originLocationId,
        sampleTypeId: presealedForm.sampleTypeId,
        sealTag: presealedForm.sealTag,
        deliveryDeadline: new Date(presealedForm.deliveryDeadline).toISOString(),
        observedTemperatureCelsius: Number(presealedForm.observedTemperatureCelsius),
        containerType: presealedForm.containerType,
      });
      setFeedback({
        type: 'success',
        message: `Pre-sealed sample registered successfully! Sample ID: ${res.sampleId}`,
      });
      await fetchWork();
      setSubtab('assignments');
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to register pre-sealed sample.' });
    } finally {
      setActionLoading(null);
    }
  };

  const isCollector = user?.activeRole === 'collection_professional';
  const isCourier = user?.activeRole === 'delivery_partner';
  const isNode = user?.activeRole === 'node_handler';
  const isLab = user?.activeRole === 'laboratory_team';

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
      {/* Subtab Navigation */}
      <div className="flex border-b border-slate-200">
        <button
          onClick={() => setSubtab('assignments')}
          className={`py-3 px-6 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            subtab === 'assignments'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <Layers className="w-4 h-4" />
          <span>Assigned Work ({workList.length})</span>
        </button>

        <button
          onClick={() => setSubtab('location')}
          className={`py-3 px-6 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            subtab === 'location'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <MapPin className="w-4 h-4" />
          <span>Record Location Update</span>
        </button>

        <button
          onClick={() => setSubtab('ingest')}
          className={`py-3 px-6 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            subtab === 'ingest'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <Package className="w-4 h-4" />
          <span>Register Pre-sealed Sample</span>
        </button>
      </div>

      {feedback && (
        <div
          className={`p-4 rounded-xl text-sm flex items-center space-x-2 ${
            feedback.type === 'success'
              ? 'bg-emerald-50 text-emerald-800 border border-emerald-200'
              : 'bg-red-50 text-red-800 border border-red-200'
          }`}
        >
          {feedback.type === 'success' ? (
            <CheckCircle2 className="w-5 h-5 text-emerald-600 flex-shrink-0" />
          ) : (
            <AlertTriangle className="w-5 h-5 text-red-600 flex-shrink-0" />
          )}
          <span>{feedback.message}</span>
        </div>
      )}

      {/* 1. Assignments Tab */}
      {subtab === 'assignments' && (
        <div className="space-y-4">
          {/* Current vs Past Tabs */}
          <div className="flex items-center space-x-2 bg-slate-100 p-1 rounded-xl w-fit">
            <button
              onClick={() => setWorkTab('current')}
              data-testid="work-tab-current"
              className={`px-4 py-1.5 rounded-lg text-xs font-bold transition ${
                workTab === 'current'
                  ? 'bg-white text-slate-900 shadow-sm'
                  : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              Current / Active ({currentWork.length})
            </button>
            <button
              onClick={() => setWorkTab('past')}
              data-testid="work-tab-past"
              className={`px-4 py-1.5 rounded-lg text-xs font-bold transition ${
                workTab === 'past'
                  ? 'bg-white text-slate-900 shadow-sm'
                  : 'text-slate-600 hover:text-slate-900'
              }`}
            >
              Past / Completed ({pastWork.length})
            </button>
          </div>

          {/* Assignment Cards List */}
          {loading ? (
            <div className="py-12 text-center text-slate-500">Loading assignments...</div>
          ) : (workTab === 'current' ? currentWork : pastWork).length === 0 ? (
            <div className="bg-white rounded-2xl border border-slate-200 p-12 text-center text-slate-500 space-y-2">
              <Layers className="w-10 h-10 text-slate-300 mx-auto" />
              <p className="font-semibold text-slate-700">No assignments found</p>
              <p className="text-xs text-slate-400">
                {workTab === 'current' ? 'No active tasks offered or assigned.' : 'No completed work history.'}
              </p>
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {(workTab === 'current' ? currentWork : pastWork).map((w) => {
                const isOffered = w.status === 'offered';
                return (
                  <div
                    key={w.id}
                    data-testid="assignment-card"
                    className="bg-white rounded-xl border border-slate-200 p-5 shadow-sm space-y-4 flex flex-col justify-between"
                  >
                    <div className="space-y-3">
                      <div className="flex items-center justify-between">
                        <div className="flex items-center space-x-2">
                          <span className="font-mono text-xs font-bold text-slate-800">
                            {w.assignment_type.replace(/_/g, ' ').toUpperCase()}
                          </span>
                          <span
                            className={`text-[10px] font-bold px-2 py-0.5 rounded uppercase ${
                              w.status === 'offered'
                                ? 'bg-amber-100 text-amber-800 animate-pulse'
                                : w.status === 'accepted' || w.status === 'in_progress'
                                ? 'bg-blue-100 text-blue-800'
                                : 'bg-emerald-100 text-emerald-800'
                            }`}
                          >
                            {w.status}
                          </span>
                        </div>
                        {w.sample_id && (
                          <button
                            onClick={() => setSelectedSampleId(w.sample_id!)}
                            className="text-xs text-teal-600 hover:text-teal-700 font-semibold underline"
                          >
                            Sample {w.sample_id.slice(0, 8)}...
                          </button>
                        )}
                      </div>

                      {/* Origin & Destination / Target */}
                      <div className="bg-slate-50 p-3 rounded-lg border border-slate-200 space-y-1.5 text-xs text-slate-700">
                        <div className="flex items-start justify-between">
                          <span className="text-slate-500">From / Origin:</span>
                          <span className="font-semibold text-slate-900 text-right">
                            {w.from_location_name || (w.from_latitude ? `${w.from_latitude.toFixed(4)}, ${w.from_longitude?.toFixed(4)}` : 'Collection Point')}
                          </span>
                        </div>
                        <div className="flex items-start justify-between">
                          <span className="text-slate-500">To / Destination:</span>
                          <span className="font-semibold text-slate-900 text-right">
                            {w.to_location_name || w.target_location_name || (w.to_latitude ? `${w.to_latitude.toFixed(4)}, ${w.to_longitude?.toFixed(4)}` : 'Network Hub / Lab')}
                          </span>
                        </div>
                        {w.deadline && (
                          <div className="flex items-center justify-between pt-1 border-t border-slate-200 text-slate-500">
                            <span>Deadline:</span>
                            <span className="font-bold text-slate-800">
                              {new Date(w.deadline).toLocaleTimeString()}
                            </span>
                          </div>
                        )}
                      </div>
                    </div>

                    {/* Action Controls */}
                    <div className="pt-2 border-t border-slate-100 flex flex-wrap gap-2">
                      {isOffered ? (
                        <>
                          <button
                            onClick={() => handleAcceptAssignment(w.id)}
                            disabled={actionLoading === w.id}
                            data-testid="accept-assignment-button"
                            className="flex-1 py-2 px-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-bold shadow-sm transition disabled:opacity-50"
                          >
                            Accept Assignment
                          </button>
                          <button
                            onClick={() => handleDeclineAssignment(w.id)}
                            disabled={actionLoading === w.id}
                            data-testid="decline-assignment-button"
                            className="py-2 px-3 bg-slate-200 hover:bg-slate-300 text-slate-700 rounded-lg text-xs font-bold transition disabled:opacity-50"
                          >
                            Decline
                          </button>
                        </>
                      ) : (
                        <>
                          {/* Role Specific Actions */}
                          {isCollector && w.status !== 'completed' && w.sample_id && (
                            <button
                              onClick={() => setCollectModal({ assignmentId: w.id, sampleId: w.sample_id! })}
                              className="py-1.5 px-3 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-xs font-bold"
                            >
                              Collect & Seal Sample
                            </button>
                          )}

                          {w.sample_id && w.status !== 'completed' && (
                            <button
                              onClick={() => setCheckpointModal({ sampleId: w.sample_id! })}
                              className="py-1.5 px-3 bg-slate-700 hover:bg-slate-800 text-white rounded-lg text-xs font-semibold"
                            >
                              Record Checkpoint
                            </button>
                          )}

                          {isLab && w.status !== 'completed' && w.sample_id && (
                            <>
                              <button
                                onClick={() => setLabReceiptModal({ sampleId: w.sample_id! })}
                                className="py-1.5 px-3 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-xs font-bold"
                              >
                                Confirm Lab Receipt
                              </button>
                              <button
                                onClick={() => setLabExceptionModal({ sampleId: w.sample_id! })}
                                className="py-1.5 px-3 bg-red-600 hover:bg-red-700 text-white rounded-lg text-xs font-bold"
                              >
                                Record Exception
                              </button>
                            </>
                          )}
                        </>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      )}

      {/* 2. Record Location Tab */}
      {subtab === 'location' && (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-6 max-w-xl">
          <div>
            <h2 className="text-xl font-bold text-slate-900">Record Live Location Update</h2>
            <p className="text-xs text-slate-500">
              Transmit your current GPS coordinates to update your availability and freshness status on the live dispatch map.
            </p>
          </div>

          <form onSubmit={handleRecordLocation} className="space-y-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Latitude
              </label>
              <input
                type="number"
                step="any"
                required
                data-testid="worker-latitude-input"
                value={locationForm.latitude}
                onChange={(e) => setLocationForm({ ...locationForm, latitude: parseFloat(e.target.value) })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Longitude
              </label>
              <input
                type="number"
                step="any"
                required
                data-testid="worker-longitude-input"
                value={locationForm.longitude}
                onChange={(e) => setLocationForm({ ...locationForm, longitude: parseFloat(e.target.value) })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Accuracy (meters)
                </label>
                <input
                  type="number"
                  value={locationForm.accuracyMeters}
                  onChange={(e) => setLocationForm({ ...locationForm, accuracyMeters: parseFloat(e.target.value) })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Speed (m/s)
                </label>
                <input
                  type="number"
                  value={locationForm.speedMps}
                  onChange={(e) => setLocationForm({ ...locationForm, speedMps: parseFloat(e.target.value) })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>
            </div>

            <button
              type="submit"
              data-testid="record-location-submit-button"
              disabled={actionLoading === 'location'}
              className="w-full py-2.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-bold shadow-sm transition disabled:opacity-50"
            >
              {actionLoading === 'location' ? 'Transmitting Location...' : 'Record Location'}
            </button>
          </form>
        </div>
      )}

      {/* 3. Presealed Ingestion Tab */}
      {subtab === 'ingest' && (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm space-y-6 max-w-2xl">
          <div>
            <h2 className="text-xl font-bold text-slate-900">Register Pre-sealed Clinical Sample</h2>
            <p className="text-xs text-slate-500">
              Ingest a sample that was already collected and sealed prior to entering the transport network.
              Origin must be an active clinic or network node.
            </p>
          </div>

          <form onSubmit={handleIngestPresealed} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Origin Facility / Node
              </label>
              <select
                value={presealedForm.originLocationId}
                onChange={(e) => setPresealedForm({ ...presealedForm, originLocationId: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
              >
                {locations.map((loc) => (
                  <option key={loc.id} value={loc.id}>
                    {loc.name} ({loc.type})
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Sample Type
              </label>
              <select
                value={presealedForm.sampleTypeId}
                onChange={(e) => setPresealedForm({ ...presealedForm, sampleTypeId: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
              >
                {sampleTypes.map((st) => (
                  <option key={st.id} value={st.id}>
                    {st.name} ({st.code}) - {st.requires_cooling ? 'Cold Chain' : 'Ambient'}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Seal Tag Identifier
              </label>
              <input
                type="text"
                required
                value={presealedForm.sealTag}
                onChange={(e) => setPresealedForm({ ...presealedForm, sealTag: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Observed Temperature (°C)
              </label>
              <input
                type="number"
                step="0.1"
                required
                value={presealedForm.observedTemperatureCelsius}
                onChange={(e) => setPresealedForm({ ...presealedForm, observedTemperatureCelsius: parseFloat(e.target.value) })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Container Type
              </label>
              <input
                type="text"
                required
                value={presealedForm.containerType}
                onChange={(e) => setPresealedForm({ ...presealedForm, containerType: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Delivery Deadline
              </label>
              <input
                type="datetime-local"
                required
                value={presealedForm.deliveryDeadline}
                onChange={(e) => setPresealedForm({ ...presealedForm, deliveryDeadline: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div className="md:col-span-2 pt-2">
              <button
                type="submit"
                disabled={actionLoading === 'ingest'}
                className="px-6 py-2.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-bold shadow-sm transition disabled:opacity-50"
              >
                {actionLoading === 'ingest' ? 'Registering...' : 'Register Pre-sealed Sample'}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Collect & Seal Modal */}
      {collectModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-900">Record Sample Collection & Sealing</h3>
            <form onSubmit={handleCollectAndSeal} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Container Type
                </label>
                <input
                  type="text"
                  required
                  value={collectForm.containerType}
                  onChange={(e) => setCollectForm({ ...collectForm, containerType: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Seal Tag Number
                </label>
                <input
                  type="text"
                  required
                  value={collectForm.sealTag}
                  onChange={(e) => setCollectForm({ ...collectForm, sealTag: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Observed Temperature (°C)
                </label>
                <input
                  type="number"
                  step="0.1"
                  required
                  value={collectForm.temp}
                  onChange={(e) => setCollectForm({ ...collectForm, temp: parseFloat(e.target.value) })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
