                <button
                  type="submit"
                  className="px-4 py-2 bg-purple-600 hover:bg-purple-700 text-white rounded-lg text-sm font-bold"
                >
                  Split Batch
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Merge Modal */}
      {mergeModal && (
        <div className="fixed inset-0 z-50 bg-slate-900/60 backdrop-blur-sm flex items-center justify-center p-4">
          <div className="bg-white rounded-2xl shadow-xl max-w-md w-full p-6 space-y-4">
            <h3 className="text-lg font-bold text-slate-900">Merge Journeys</h3>
            <form onSubmit={handleMerge} className="space-y-3">
              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Target Journey ID
                </label>
                <input
                  type="text"
                  required
                  value={mergeForm.targetJourneyId}
                  onChange={(e) => setMergeForm({ ...mergeForm, targetJourneyId: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Expected Plan Version
                </label>
                <input
                  type="number"
                  min="1"
                  required
                  value={mergeForm.expectedPlanVersion}
                  onChange={(e) => setMergeForm({ ...mergeForm, expectedPlanVersion: parseInt(e.target.value) || 1 })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                  Source Journey IDs (comma-separated)
                </label>
                <input
                  type="text"
                  required
                  placeholder="uuid1, uuid2"
                  value={mergeForm.sourceJourneyIdsStr}
                  onChange={(e) => setMergeForm({ ...mergeForm, sourceJourneyIdsStr: e.target.value })}
                  className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
                />
              </div>

              <div className="flex justify-end space-x-2 pt-3">
                <button
                  type="button"
                  onClick={() => setMergeModal(false)}
                  className="px-4 py-2 border border-slate-300 rounded-lg text-sm font-medium text-slate-700"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg text-sm font-bold"
                >
                  Merge Journeys
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Sample Detail Modal */}
      {selectedSampleId && (
        <SampleDetailModal
          sampleId={selectedSampleId}
          onClose={() => setSelectedSampleId(null)}
        />
      )}
    </div>
  );
};
"}

{"file_text":"import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { AuditRecord } from '../types';
import { Search, ShieldAlert, Clock, User, FileText, CheckCircle2, XCircle } from 'lucide-react';

export const AuditView: React.FC = () => {
  const [records, setRecords] = useState<AuditRecord[]>([]);
  const [loading, setLoading] = useState(false);
  const [filters, setFilters] = useState({
    entityType: '',
    entityId: '',
    actorUserId: '',
    actorRole: '',
    action: '',
  });

  const searchAudit = async () => {
    try {
      setLoading(true);
      const res = await api.searchAuditTrail({
        entityType: filters.entityType || undefined,
        entityId: filters.entityId || undefined,
        actorUserId: filters.actorUserId || undefined,
        actorRole: filters.actorRole || undefined,
        action: filters.action || undefined,
        limit: 100,
      });
      setRecords(res || []);
    } catch (err: any) {
      console.error('Audit search error:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    searchAudit();
  }, []);

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    searchAudit();
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6" data-testid="audit-view">
      <div>
        <h2 className="text-xl font-bold text-slate-900" data-testid="audit-view-title">
          Audit Trail & Security Logs
        </h2>
        <p className="text-xs text-slate-500">
          Search tamper-evident audit records covering sign-ins, custody handoffs, overrides, and exceptions.
        </p>
      </div>

      {/* Search Filters Card */}
      <form onSubmit={handleSearchSubmit} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm space-y-4">
        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-5 gap-3">
          <div>
            <label className="block text-[11px] font-semibold text-slate-600 uppercase mb-1">
              Entity Type
            </label>
            <select
              value={filters.entityType}
              onChange={(e) => setFilters({ ...filters, entityType: e.target.value })}
              className="w-full px-2.5 py-1.5 border border-slate-300 rounded-lg text-xs bg-white"
            >
              <option value="">All Entities</option>
              <option value="sample">Sample</option>
              <option value="journey">Journey</option>
              <option value="assignment">Assignment</option>
              <option value="location">Location</option>
              <option value="user">User</option>
            </select>
          </div>

          <div>
            <label className="block text-[11px] font-semibold text-slate-600 uppercase mb-1">
              Entity ID
            </label>
            <input
              type="text"
              placeholder="UUID"
              value={filters.entityId}
              onChange={(e) => setFilters({ ...filters, entityId: e.target.value })}
              className="w-full px-2.5 py-1.5 border border-slate-300 rounded-lg text-xs"
            />
          </div>

          <div>
            <label className="block text-[11px] font-semibold text-slate-600 uppercase mb-1">
              Actor Role
            </label>
            <select
              value={filters.actorRole}
              onChange={(e) => setFilters({ ...filters, actorRole: e.target.value })}
              className="w-full px-2.5 py-1.5 border border-slate-300 rounded-lg text-xs bg-white"
            >
              <option value="">All Roles</option>
              <option value="requester">Requester</option>
              <option value="collection_professional">Collection Pro</option>
              <option value="delivery_partner">Relay Courier</option>
              <option value="node_handler">Node Handler</option>
              <option value="laboratory_team">Lab Team</option>
              <option value="dispatcher">Dispatcher</option>
              <option value="administrator">Administrator</option>
            </select>
          </div>

          <div>
            <label className="block text-[11px] font-semibold text-slate-600 uppercase mb-1">
              Action Name
            </label>
            <input
              type="text"
              placeholder="e.g. handoff, create"
              value={filters.action}
              onChange={(e) => setFilters({ ...filters, action: e.target.value })}
              className="w-full px-2.5 py-1.5 border border-slate-300 rounded-lg text-xs"
            />
          </div>

          <div className="flex items-end">
            <button
              type="submit"
              data-testid="search-audit-button"
              disabled={loading}
              className="w-full py-2 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-xs font-bold shadow-sm transition flex items-center justify-center space-x-1"
            >
              <Search className="w-3.5 h-3.5" />
              <span>{loading ? 'Searching...' : 'Search Audit'}</span>
            </button>
          </div>
        </div>
      </form>

      {/* Audit Records Table */}
      <div className="bg-white rounded-xl border border-slate-200 overflow-hidden shadow-sm">
        <table className="min-w-full divide-y divide-slate-200 text-left text-xs" data-testid="audit-table">
          <thead className="bg-slate-50 text-slate-500 uppercase font-semibold">
            <tr>
              <th className="px-4 py-3">Timestamp</th>
              <th className="px-4 py-3">Actor</th>
              <th className="px-4 py-3">Role</th>
              <th className="px-4 py-3">Action</th>
              <th className="px-4 py-3">Target Entity</th>
              <th className="px-4 py-3">Outcome</th>
              <th className="px-4 py-3">Change Details</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100 font-medium text-slate-700">
            {records.length === 0 ? (
              <tr>
                <td colSpan={7} className="px-4 py-8 text-center text-slate-400">
                  No audit trail records found for these search parameters.
                </td>
              </tr>
            ) : (
              records.map((r) => {
                const isSuccess = r.outcome === 'success';
                return (
                  <tr key={r.id} className="hover:bg-slate-50/80 transition">
                    <td className="px-4 py-3 text-slate-500 whitespace-nowrap">
                      {new Date(r.timestamp).toLocaleString()}
                    </td>
                    <td className="px-4 py-3 font-semibold text-slate-900">
                      {r.actor_name || r.actor_user_id || 'System'}
                    </td>
                    <td className="px-4 py-3 capitalize text-slate-600">
                      {r.actor_role ? r.actor_role.replace(/_/g, ' ') : 'N/A'}
                    </td>
                    <td className="px-4 py-3 font-mono text-[11px] font-bold text-teal-800">
                      {r.action}
                    </td>
                    <td className="px-4 py-3 text-slate-600">
                      <span className="font-semibold text-slate-800 uppercase text-[10px] bg-slate-100 px-1.5 py-0.5 rounded mr-1">
                        {r.entity_type}
                      </span>
                      <span className="font-mono">{r.entity_id ? `${r.entity_id.slice(0, 8)}...` : ''}</span>
                    </td>
                    <td className="px-4 py-3">
                      <span
                        className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase ${
                          isSuccess ? 'bg-emerald-100 text-emerald-800' : 'bg-red-100 text-red-800'
                        }`}
                      >
                        {isSuccess ? (
                          <CheckCircle2 className="w-3 h-3 mr-1" />
                        ) : (
                          <XCircle className="w-3 h-3 mr-1" />
                        )}
                        {r.outcome}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-slate-500 max-w-xs truncate font-mono text-[10px]">
                      {r.changes ? JSON.stringify(r.changes) : '-'}
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};
