{"command":"create","security_risk":"LOW","summary":"Create AdminSettingsView component","path":"/workspace/frontend/src/pages/AdminSettingsView.tsx","file_text":"import React, { useState, useEffect } from 'react';
import { api } from '../api/client';
import { NetworkLocation, SampleType } from '../types';
import { Shield, Plus, CheckCircle2, AlertCircle, MapPin, Layers, Users, Zap } from 'lucide-react';

export const AdminSettingsView: React.FC = () => {
  const [tab, setTab] = useState<'users' | 'locations' | 'sample_types'>('users');
  const [locations, setLocations] = useState<NetworkLocation[]>([]);
  const [sampleTypes, setSampleTypes] = useState<SampleType[]>([]);
  const [loading, setLoading] = useState(false);
  const [feedback, setFeedback] = useState<{ type: 'success' | 'error'; message: string } | null>(null);

  // Create User Form
  const [userForm, setUserForm] = useState({
    username: '',
    password: '',
    fullName: '',
    roles: ['delivery_partner'],
    assignedNodeId: '',
    assignedLaboratoryId: '',
    certifications: 'Amber,Indigo,Frost,Pulse',
  });

  // Create Location Form
  const [locForm, setLocForm] = useState({
    id: '',
    name: '',
    type: 'collection_centre',
    latitude: 12.9716,
    longitude: 77.5946,
    address: 'Bangalore East',
    functions: ['collection_point', 'transfer_point'],
    capacityUnits: 100,
    cooledCapacityUnits: 40,
  });

  // Create Sample Type Form
  const [stForm, setStForm] = useState({
    id: '',
    name: '',
    code: '',
    requiresCooling: false,
    minTemp: 15,
    maxTemp: 25,
    allowedContainers: 'standard_tube,vial',
    incompatibleWith: '',
    requiresCertifiedCollector: true,
    requiredQualification: '',
  });

  const fetchData = async () => {
    try {
      setLoading(true);
      const snap = await api.readServiceabilitySnapshot();
      if (snap) {
        if (snap.nodes) setLocations(snap.nodes);
        if (snap.sample_types) setSampleTypes(snap.sample_types);
      }
    } catch (err: any) {
      console.error('Failed to load admin data:', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, []);

  const handleCreateUser = async (e: React.FormEvent) => {
    e.preventDefault();
    setFeedback(null);
    try {
      const certs = userForm.certifications.split(',').map((s) => s.trim()).filter(Boolean);
      await api.createUser({
        username: userForm.username,
        password: userForm.password,
        fullName: userForm.fullName,
        roles: userForm.roles,
        assignedNodeId: userForm.assignedNodeId || undefined,
        assignedLaboratoryId: userForm.assignedLaboratoryId || undefined,
        certifications: certs,
      });
      setFeedback({ type: 'success', message: `User '${userForm.username}' created successfully!` });
      setUserForm({
        username: '',
        password: '',
        fullName: '',
        roles: ['delivery_partner'],
        assignedNodeId: '',
        assignedLaboratoryId: '',
        certifications: 'Amber,Indigo,Frost,Pulse',
      });
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to create user' });
    }
  };

  const handleCreateLocation = async (e: React.FormEvent) => {
    e.preventDefault();
    setFeedback(null);
    try {
      await api.createLocation({
        name: locForm.name,
        type: locForm.type,
        latitude: Number(locForm.latitude),
        longitude: Number(locForm.longitude),
        address: locForm.address,
        functions: locForm.functions,
        capacityUnits: Number(locForm.capacityUnits),
        cooledCapacityUnits: Number(locForm.cooledCapacityUnits),
      });
      setFeedback({ type: 'success', message: `Location '${locForm.name}' created successfully!` });
      await fetchData();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to create location' });
    }
  };

  const handleCreateSampleType = async (e: React.FormEvent) => {
    e.preventDefault();
    setFeedback(null);
    try {
      const containers = stForm.allowedContainers.split(',').map((s) => s.trim()).filter(Boolean);
      const incompat = stForm.incompatibleWith.split(',').map((s) => s.trim()).filter(Boolean);
      await api.createSampleType({
        name: stForm.name,
        code: stForm.code,
        requiresCooling: stForm.requiresCooling,
        minTemperatureCelsius: Number(stForm.minTemp),
        maxTemperatureCelsius: Number(stForm.maxTemp),
        allowedContainers: containers,
        incompatibleWith: incompat,
        requiresCertifiedCollector: stForm.requiresCertifiedCollector,
        requiredQualification: stForm.requiredQualification || undefined,
      });
      setFeedback({ type: 'success', message: `Sample type '${stForm.name}' created successfully!` });
      await fetchData();
    } catch (err: any) {
      setFeedback({ type: 'error', message: err.message || 'Failed to create sample type' });
    }
  };

  return (
    <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-6">
      <div>
        <h2 className="text-xl font-bold text-slate-900" data-testid="admin-view-title">
          System Administration & Configuration
        </h2>
        <p className="text-xs text-slate-500">
          Configure personnel access, network nodes, laboratory capabilities, and sample handling types.
        </p>
      </div>

      {/* Tabs */}
      <div className="flex border-b border-slate-200">
        <button
          onClick={() => setTab('users')}
          className={`py-3 px-6 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            tab === 'users'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <Users className="w-4 h-4" />
          <span>User Onboarding</span>
        </button>

        <button
          onClick={() => setTab('locations')}
          className={`py-3 px-6 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            tab === 'locations'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <MapPin className="w-4 h-4" />
          <span>Locations & Facilities</span>
        </button>

        <button
          onClick={() => setTab('sample_types')}
          className={`py-3 px-6 font-semibold text-sm border-b-2 flex items-center space-x-2 ${
            tab === 'sample_types'
              ? 'border-teal-600 text-teal-700'
              : 'border-transparent text-slate-500 hover:text-slate-700'
          }`}
        >
          <Zap className="w-4 h-4" />
          <span>Sample Types</span>
        </button>
      </div>

      {feedback && (
        <div
          className={`p-4 rounded-xl text-sm flex items-center space-x-2 ${
            feedback.type === 'success'
              ? 'bg-emerald-50 text-emerald-800 border border-emerald-200'
              : 'bg-red-50 text-red-800 border border-red-200'
          }`}
        >
          {feedback.type === 'success' ? (
            <CheckCircle2 className="w-5 h-5 text-emerald-600 flex-shrink-0" />
          ) : (
            <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0" />
          )}
          <span>{feedback.message}</span>
        </div>
      )}

      {/* 1. User Onboarding */}
      {tab === 'users' && (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm max-w-2xl">
          <h3 className="text-base font-bold text-slate-900 mb-4">Create New Network User</h3>
          <form onSubmit={handleCreateUser} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Username
              </label>
              <input
                type="text"
                required
                value={userForm.username}
                onChange={(e) => setUserForm({ ...userForm, username: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Password
              </label>
              <input
                type="password"
                required
                value={userForm.password}
                onChange={(e) => setUserForm({ ...userForm, password: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Full Name
              </label>
              <input
                type="text"
                required
                value={userForm.fullName}
                onChange={(e) => setUserForm({ ...userForm, fullName: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Assigned Node
              </label>
              <select
                value={userForm.assignedNodeId}
                onChange={(e) => setUserForm({ ...userForm, assignedNodeId: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
              >
                <option value="">None</option>
                {locations.map((loc) => (
                  <option key={loc.id} value={loc.id}>
                    {loc.name}
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Assigned Laboratory
              </label>
              <select
                value={userForm.assignedLaboratoryId}
                onChange={(e) => setUserForm({ ...userForm, assignedLaboratoryId: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
              >
                <option value="">None</option>
                {locations.filter((l) => l.type === 'laboratory' || l.functions?.includes('laboratory')).map((loc) => (
                  <option key={loc.id} value={loc.id}>
                    {loc.name}
                  </option>
                ))}
              </select>
            </div>

            <div className="md:col-span-2">
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Certifications (comma-separated)
              </label>
              <input
                type="text"
                value={userForm.certifications}
                onChange={(e) => setUserForm({ ...userForm, certifications: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div className="md:col-span-2 pt-2">
              <button
                type="submit"
                className="px-6 py-2.5 bg-teal-600 hover:bg-teal-700 text-white rounded-lg text-sm font-bold shadow-sm transition"
              >
                Create User
              </button>
            </div>
          </form>
        </div>
      )}

      {/* 2. Locations */}
      {tab === 'locations' && (
        <div className="bg-white rounded-2xl border border-slate-200 p-6 shadow-sm max-w-2xl">
          <h3 className="text-base font-bold text-slate-900 mb-4">Register New Location / Facility</h3>
          <form onSubmit={handleCreateLocation} className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Location Name
              </label>
              <input
                type="text"
                required
                value={locForm.name}
                onChange={(e) => setLocForm({ ...locForm, name: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Type
              </label>
              <select
                value={locForm.type}
                onChange={(e) => setLocForm({ ...locForm, type: e.target.value })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm bg-white"
              >
                <option value="collection_centre">Collection Centre</option>
                <option value="hub">Hub</option>
                <option value="laboratory">Laboratory</option>
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Latitude
              </label>
              <input
                type="number"
                step="any"
                required
                value={locForm.latitude}
                onChange={(e) => setLocForm({ ...locForm, latitude: parseFloat(e.target.value) })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Longitude
              </label>
              <input
                type="number"
                step="any"
                required
                value={locForm.longitude}
                onChange={(e) => setLocForm({ ...locForm, longitude: parseFloat(e.target.value) })}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm"
              />
            </div>

            <div>
              <label className="block text-xs font-semibold text-slate-700 uppercase mb-1">
                Regular Capacity Units
              </label>
              <input
                type="number"
                required
                value={locForm.capacityUnits}
