{"summary":"Create App component","file_text":"import React, { useState, useEffect } from 'react';
import { useAuth } from './context/AuthContext';
import { Navbar } from './components/Navbar';
import { LoginPage } from './pages/LoginPage';
import { RequesterView } from './pages/RequesterView';
import { WorkerWorkView } from './pages/WorkerWorkView';
import { CapacityView } from './pages/CapacityView';
import { DispatcherDashboard } from './pages/DispatcherDashboard';
import { AuditView } from './pages/AuditView';
import { AdminSettingsView } from './pages/AdminSettingsView';
import { MapView } from './components/MapView';
import { api } from './api/client';
import { OperationsState } from './types';

export const App: React.FC = () => {
  const { user, isAuthenticated, isLoading } = useAuth();
  const [currentTab, setCurrentTab] = useState<string>('samples');
  const [opsData, setOpsData] = useState<OperationsState | null>(null);

  useEffect(() => {
    if (user) {
      const role = user.activeRole;
      if (role === 'requester') setCurrentTab('samples');
      else if (role === 'dispatcher' || role === 'administrator') setCurrentTab('operations');
      else if (role === 'laboratory_team') setCurrentTab('assignments');
      else if (role === 'node_handler') setCurrentTab('assignments');
      else setCurrentTab('assignments');
    }
  }, [user?.activeRole]);

  useEffect(() => {
    if (isAuthenticated) {
      api.readOperationsState().then(setOpsData).catch(console.error);
    }
  }, [isAuthenticated, currentTab]);

  if (isLoading) {
    return (
      <div className="min-h-screen bg-slate-950 flex items-center justify-center text-white">
        <div className="animate-pulse font-medium text-teal-400">Loading application...</div>
      </div>
    );
  }

  if (!isAuthenticated || !user) {
    return <LoginPage />;
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <Navbar currentTab={currentTab} onTabChange={setCurrentTab} />

      <main className="flex-1 pb-12">
        {/* Requester Tabs */}
        {currentTab === 'samples' && <RequesterView initialTab="samples" />}
        {currentTab === 'serviceability' && <RequesterView initialTab="serviceability" />}
        {currentTab === 'create_request' && <RequesterView initialTab="create_request" />}

        {/* Worker Tabs */}
        {currentTab === 'assignments' && <WorkerWorkView initialSubtab="assignments" />}
        {currentTab === 'ingest' && <WorkerWorkView initialSubtab="ingest" />}

        {/* Capacity Tab */}
        {currentTab === 'capacity' && <CapacityView />}

        {/* Operations Dashboard */}
        {currentTab === 'operations' && <DispatcherDashboard />}

        {/* Audit View */}
        {currentTab === 'audit' && <AuditView />}

        {/* Administration */}
        {currentTab === 'admin' && <AdminSettingsView />}

        {/* Live Map Full View */}
        {currentTab === 'map' && (
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8 space-y-4">
            <div className="flex justify-between items-center">
              <div>
                <h2 className="text-xl font-bold text-slate-900">Live Transport & Operations Map</h2>
                <p className="text-xs text-slate-500">
                  Real-time network view of collection centres, hubs, laboratories, couriers, and samples.
                </p>
              </div>
            </div>
            <MapView
              locations={opsData?.locations || []}
              workers={opsData?.workers || []}
              samples={opsData?.samples || []}
              height="700px"
            />
          </div>
        )}
      </main>
    </div>
  );
};
